var scanControls = { id: 'scan-vmware-controls', version: '1.0.0', run: async function(params, ctx) {
  var exec = ctx.exec;
  if (!exec) return { ok: false, error: 'exec no disponible' };

  var ps = [
    'Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue',
    'Add-Type @"',
    'using System;',
    'using System.Runtime.InteropServices;',
    'public class Win32 {',
    '    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();',
    '    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, System.Text.StringBuilder text, int count);',
    '    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);',
    '    public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }',
    '}',
    '"@',

    '# Find VMware main window',
    '$vmProc = Get-Process -Name "vmware" -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne [IntPtr]::Zero } | Select-Object -First 1',
    'if (-not $vmProc) { Write-Output "ERROR=VMware not found"; return }',
    '$vmHwnd = $vmProc.MainWindowHandle',
    'Write-Output "VMWARE_HANDLE=$vmHwnd"',

    '# Get window rect',
    '$rect = New-Object Win32+RECT',
    '[Win32]::GetWindowRect($vmHwnd, [ref]$rect) | Out-Null',
    'Write-Output "VMWARE_RECT=Left=$($rect.Left) Top=$($rect.Top) Right=$($rect.Right) Bottom=$($rect.Bottom)"',
    'Write-Output "VMWARE_SIZE=Width=$($rect.Right - $rect.Left) Height=$($rect.Bottom - $rect.Top)"',

    '# Use UI Automation to enumerate controls',
    'try {',
    '  Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop',
    '  Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop',
    '  $root = [System.Windows.Automation.AutomationElement]::FromHandle($vmHwnd)',
    '  Write-Output "UIA_ROOT_FOUND=true"',
    '  ',
    '  # Get all descendant controls',
    '  $all = $root.FindAll([System.Windows.Automation.TreeScope]::Descendants, [System.Windows.Automation.Condition]::TrueCondition)',
    '  Write-Output "UIA_TOTAL_CONTROLS=$($all.Count)"',
    '  ',
    '  $i = 0',
    '  foreach ($el in $all) {',
    '    try {',
    '      $name = $el.Current.Name',
    '      $ctrlType = $el.Current.ControlType.ProgrammaticName',
    '      $automationId = $el.Current.AutomationId',
    '      $className = $el.Current.ClassName',
    '      $bounds = $el.Current.BoundingRectangle',
    '      $enabled = $el.Current.IsEnabled',
    '      ',
    '      # Calculate center point',
    '      $cx = [math]::Round($bounds.X + $bounds.Width / 2)',
    '      $cy = [math]::Round($bounds.Y + $bounds.Height / 2)',
    '      ',
    '      Write-Output "CTRL[$i]: Name=$name | Type=$ctrlType | AutoId=$automationId | Class=$className | Bounds=X=$([math]::Round($bounds.X)),Y=$([math]::Round($bounds.Y)),W=$([math]::Round($bounds.Width)),H=$([math]::Round($bounds.Height)) | Center=$cx,$cy | Enabled=$enabled"',
    '      $i++',
    '    } catch {}',
    '  }',
    '} catch {',
    '  Write-Output "UIA_ERROR=$($_.Exception.Message)"',
    '  ',
    '  # Fallback: use SendMessage to get child windows',
    '  Add-Type @"',
    '  using System;',
    '  using System.Runtime.InteropServices;',
    '  using System.Text;',
    '  public class WinEnum {',
    '    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);',
    '    [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern IntPtr GetParent(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);',
    '    public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }',
    '  }',
    '"@',
    '  ',
    '  $children = @()',
    '  $callback = [WinEnum+EnumWindowsProc] {',
    '    param($hWnd, $lParam)',
    '    $parent = [WinEnum]::GetParent($hWnd)',
    '    if ($parent -eq $vmHwnd) {',
    '      $len = [WinEnum]::GetWindowTextLength($hWnd)',
    '      $sb = New-Object System.Text.StringBuilder($len + 1)',
    '      [WinEnum]::GetWindowText($hWnd, $sb, $sb.Capacity) | Out-Null',
    '      $title = $sb.ToString()',
    '      $vis = [WinEnum]::IsWindowVisible($hWnd)',
    '      $r = New-Object WinEnum+RECT',
    '      [WinEnum]::GetWindowRect($hWnd, [ref]$r) | Out-Null',
    '      Write-Output "CHILD: Handle=$hWnd | Title=$title | Visible=$vis | Rect=Left=$($r.Left),Top=$($r.Top),Right=$($r.Right),Bottom=$($r.Bottom)"',
    '    }',
    '    return $true',
    '  }',
    '  [WinEnum]::EnumWindows($callback, [IntPtr]::Zero) | Out-Null',
    '  Write-Output "ENUM_DONE=true"',
    '}'
  ].join('\r\n');

  try {
    var raw = await exec(ps);
    return { ok: true, output: raw, at: new Date().toISOString() };
  } catch (e) {
    return { ok: false, error: e.message };
  }
} };
